import { useState, useRef } from "react";
import gameService from '../../services/gameService';

function GameConstructor() {
  const [gameType, setGameType] = useState('wheel');
  const [gameContent, setGameContent] = useState(null);
  const [gameName, setGameName] = useState('My Test Wheel Game');
  const [isSaving, setIsSaving] = useState(false);
  const [saveMessage, setSaveMessage] = useState('');
  const [wheelItems, setWheelItems] = useState([
    { wordId: 1, wordLabel: "Math", color: "#FF6B6B", textPosition: { x: 0, y: 0 } },
    { wordId: 2, wordLabel: "Science", color: "#4ECDC4", textPosition: { x: 0, y: 0 } },
    { wordId: 3, wordLabel: "History", color: "#45B7D1", textPosition: { x: 0, y: 0 } },
    { wordId: 4, wordLabel: "Art", color: "#96CEB4", textPosition: { x: 0, y: 0 } },
    { wordId: 5, wordLabel: "Music", color: "#FFEAA7", textPosition: { x: 0, y: 0 } },
    { wordId: 6, wordLabel: "Sports", color: "#DDA0DD", textPosition: { x: 0, y: 0 } },
  ]);

  const handleGameNaming = (event) => {
    setGameName(event.target.value);
  };

  const handleContent = () => {
    setGameContent();
  };

  const handleSaveGame = async () => {
    if (!gameName.trim()) {
      setSaveMessage('Пожалуйста, введите название игры');
      return;
    }

    if (gameType === 'wheel' && wheelItems.length === 0) {
      setSaveMessage('Добавьте хотя бы один элемент в колесо');
      return;
    }

    setIsSaving(true);
    setSaveMessage('');

    try {
      await gameService.saveWheelGame(gameName, wheelItems);
      setSaveMessage('Игра успешно сохранена!');
    } catch (error) {
      console.error('Ошибка при сохранении игры:', error);
      setSaveMessage('Ошибка при сохранении игры');
    } finally {
      setIsSaving(false);
    }
  };

  function ConstructorEngine(gameType, gameContent, gameName) {
    if (gameType === 'wheel') {
      return (
        <WheelGame 
          gameName={gameName} 
          items={wheelItems}
          onItemsChange={setWheelItems}
        />
      );
    } else if (gameType === 'match') {
      return (
        <div className="mt-8 p-6 bg-white rounded-xl shadow-lg">
          <h3 className="text-xl font-bold text-gray-800 mb-4">Match Game: {gameName || 'Untitled Game'}</h3>
          <p className="text-gray-600">Matching game functionality coming soon!</p>
        </div>
      );
    } else if (gameType === 'quiz') {
      return (
        <div className="mt-8 p-6 bg-white rounded-xl shadow-lg">
          <h3 className="text-xl font-bold text-gray-800 mb-4">Quiz Game: {gameName || 'Untitled Game'}</h3>
          <p className="text-gray-600">Quiz game functionality coming soon!</p>
        </div>
      );
    }
    return null;
  }
        
//-----------------------------------------------------
// Render Games
//-----------------------------------------------------
  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 p-4">
      <div className="max-w-4xl mx-auto">
        <div className="text-center mb-8">
          <h1 className="text-4xl font-bold text-gray-800 mb-2">Game Constructor</h1>
          <p className="text-gray-600">Create and customize your interactive games</p>
        </div>
        
        <div className="bg-white rounded-xl shadow-lg p-6 mb-8">
          <form onSubmit={(e) => e.preventDefault()} className="mb-6">
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Enter game name
              <input
                type="text"
                value={gameName}
                onChange={handleGameNaming}
                className="mt-1 block w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                placeholder="My Awesome Game"
              />
            </label>
          </form>
          
          <div className="flex flex-wrap gap-3 justify-center">
            <button
              type="button"
              onClick={() => setGameType('wheel')}
              className={`px-6 py-3 rounded-lg font-semibold transition-all duration-200 ${
                gameType === 'wheel'
                  ? 'bg-blue-600 text-white shadow-lg'
                  : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
              }`}
            >
              Wheel
            </button>
            <button
              type="button"
              onClick={() => setGameType('match')}
              className={`px-6 py-3 rounded-lg font-semibold transition-all duration-200 ${
                gameType === 'match'
                  ? 'bg-blue-600 text-white shadow-lg'
                  : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
              }`}
            >
              Match
            </button>
            <button
              type="button"
              onClick={() => setGameType('quiz')}
              className={`px-6 py-3 rounded-lg font-semibold transition-all duration-200 ${
                gameType === 'quiz'
                  ? 'bg-blue-600 text-white shadow-lg'
                  : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
              }`}
            >
              Quiz
            </button>
            <button 
              type="button"
              onClick={handleSaveGame}
              disabled={isSaving || !gameName.trim()}
              className={`px-6 py-3 rounded-lg font-semibold transition-all duration-200 ${
                isSaving || !gameName.trim()
                  ? 'bg-gray-400 cursor-not-allowed'
                  : 'bg-green-600 text-white hover:bg-green-700 shadow-lg'
              }`}
            >
              {isSaving ? 'Сохранение...' : 'Сохранить игру'}
            </button>
          </div>
          
          {saveMessage && (
            <div className={`mt-4 p-3 rounded-lg ${
              saveMessage.includes('успешно') 
                ? 'bg-green-100 text-green-700 border border-green-400' 
                : 'bg-red-100 text-red-700 border border-red-400'
            }`}>
              {saveMessage}
            </div>
          )}
        </div>
        
        {ConstructorEngine(gameType, gameContent, gameName)}
      </div>
    </div>
  );
}

export default GameConstructor;
